package net.kurobako.bonsai.collections

import java.nio.charset.StandardCharsets
import java.nio.file.Files
import java.nio.file.Path

/** The marks that make code generated, shared by the compiler plugins and the analysis. */
object Generated {

  val Annotations: Set[String] = Set(
    "javax.annotation.Generated",
    "javax.annotation.processing.Generated",
    "jakarta.annotation.Generated"
  )

  private val Header = "// Generated by the Scala Plugin for the Protocol Buffer Compiler."

  // possessive, as a backtracking loop recurses per comment and overflows on a commented-out file
  private val LeadingComments = """(?s)(?:\s+|//[^\n]*|/\*.*?\*/)*+""".r

  private val GeneratedTag = """(?<!\w)@generated(?!\w)""".r

  def file(path: Path): Boolean =
    Files.isRegularFile(path) && marked(String(Files.readAllBytes(path), StandardCharsets.UTF_8))

  def marked(text: String): Boolean = {
    val leading = LeadingComments.findPrefixOf(text).getOrElse("")
    leading.linesIterator.exists(_.trim == Header) || GeneratedTag.findFirstIn(leading).isDefined
  }
}
